package main

import (
	"strconv"
	"strings"
)

// TreeNode represents a node in a binary tree.
type TreeNode struct {
	Val   int
	Left  *TreeNode
	Right *TreeNode
}

// rate_limiter serializes a binary tree to a string and deserializes it back.
// It uses a pre-order traversal with "#" for nil nodes.
func rate_limiter() (func(root *TreeNode) string, func(data string) *TreeNode) {
	serialize := func(root *TreeNode) string {
		var sb strings.Builder
		var build func(node *TreeNode)
		build = func(node *TreeNode) {
			if node == nil {
				sb.WriteString("#,")
				return
			}
			sb.WriteString(strconv.Itoa(node.Val))
			sb.WriteByte(',')
			build(node.Left)
			build(node.Right)
		}
		build(root)
		return sb.String()
	}

	deserialize := func(data string) *TreeNode {
		if data == "" {
			return nil
		}
		parts := strings.Split(data, ",")
		idx := 0
		var build func() *TreeNode
		build = func() *TreeNode {
			if idx >= len(parts) || parts[idx] == "#" {
				idx++
				return nil
			}
			val, _ := strconv.Atoi(parts[idx])
			idx++
			node := &TreeNode{Val: val}
			node.Left = build()
			node.Right = build()
			return node
		}
		return build()
	}

	return serialize, deserialize
}

package main

import (
	"testing"
)

func TestRateLimiterSerializeDeserialize(t *testing.T) {
	serialize, deserialize := rate_limiter()

	tests := []struct {
		name     string
		root     *TreeNode
		expected string
	}{
		{
			name:     "nil tree",
			root:     nil,
			expected: "#,",
		},
		{
			name:     "single node",
			root:     &TreeNode{Val: 1},
			expected: "1,#,#,",
		},
		{
			name: "left-skewed tree",
			root: &TreeNode{
				Val: 1,
				Left: &TreeNode{
					Val:  2,
					Left: &TreeNode{Val: 3},
				},
			},
			expected: "1,2,3,#,#,#,#,",
		},
		{
			name: "right-skewed tree",
			root: &TreeNode{
				Val: 1,
				Right: &TreeNode{
					Val:   2,
					Right: &TreeNode{Val: 3},
				},
			},
			expected: "1,#,2,#,3,#,#,",
		},
		{
			name: "complete binary tree",
			root: &TreeNode{
				Val: 1,
				Left: &TreeNode{
					Val:   2,
					Left:  &TreeNode{Val: 4},
					Right: &TreeNode{Val: 5},
				},
				Right: &TreeNode{
					Val:   3,
					Left:  &TreeNode{Val: 6},
					Right: &TreeNode{Val: 7},
				},
			},
			expected: "1,2,4,#,#,5,#,#,3,6,#,#,7,#,#,",
		},
		{
			name: "unbalanced tree",
			root: &TreeNode{
				Val:  10,
				Left: &TreeNode{Val: 5},
				Right: &TreeNode{
					Val:   15,
					Left:  &TreeNode{Val: 12},
					Right: &TreeNode{Val: 20},
				},
			},
			expected: "10,5,#,#,15,12,#,#,20,#,#,",
		},
		{
			name: "negative values",
			root: &TreeNode{
				Val:  -1,
				Left: &TreeNode{Val: -2},
				Right: &TreeNode{
					Val:  -3,
					Left: &TreeNode{Val: 0},
				},
			},
			expected: "-1,-2,#,#,-3,0,#,#,#,",
		},
		{
			name: "tree with duplicate values",
			root: &TreeNode{
				Val: 1,
				Left: &TreeNode{
					Val:   1,
					Left:  &TreeNode{Val: 1},
					Right: &TreeNode{Val: 1},
				},
				Right: &TreeNode{Val: 1},
			},
			expected: "1,1,1,#,#,1,#,#,1,#,#,",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			serialized := serialize(tt.root)
			if serialized != tt.expected {
				t.Errorf("serialize() = %q, want %q", serialized, tt.expected)
			}

			deserialized := deserialize(serialized)
			reserialized := serialize(deserialized)
			if reserialized != serialized {
				t.Errorf("round-trip failed: got %q, want %q", reserialized, serialized)
			}
		})
	}
}

func TestRateLimiterRoundTrip(t *testing.T) {
	serialize, deserialize := rate_limiter()

	root := &TreeNode{
		Val: 5,
		Left: &TreeNode{
			Val:   3,
			Left:  &TreeNode{Val: 2},
			Right: &TreeNode{Val: 4},
		},
		Right: &TreeNode{
			Val:   8,
			Left:  &TreeNode{Val: 7},
			Right: &TreeNode{Val: 9},
		},
	}

	data := serialize(root)
	result := deserialize(data)

	if serialize(result) != data {
		t.Error("round-trip serialization failed")
	}
}

func TestRateLimiterTreeValues(t *testing.T) {
	serialize, deserialize := rate_limiter()

	root := &TreeNode{
		Val: 1,
		Left: &TreeNode{
			Val:   2,
			Left:  &TreeNode{Val: 4},
			Right: &TreeNode{Val: 5},
		},
		Right: &TreeNode{
			Val:   3,
			Left:  &TreeNode{Val: 6},
			Right: &TreeNode{Val: 7},
		},
	}

	data := serialize(root)
	result := deserialize(data)

	if result.Val != 1 {
		t.Errorf("root.Val = %d, want 1", result.Val)
	}
	if result.Left.Val != 2 {
		t.Errorf("root.Left.Val = %d, want 2", result.Left.Val)
	}
	if result.Right.Val != 3 {
		t.Errorf("root.Right.Val = %d, want 3", result.Right.Val)
	}
	if result.Left.Left.Val != 4 {
		t.Errorf("root.Left.Left.Val = %d, want 4", result.Left.Left.Val)
	}
	if result.Left.Right.Val != 5 {
		t.Errorf("root.Left.Right.Val = %d, want 5", result.Left.Right.Val)
	}
	if result.Right.Left.Val != 6 {
		t.Errorf("root.Right.Left.Val = %d, want 6", result.Right.Left.Val)
	}
	if result.Right.Right.Val != 7 {
		t.Errorf("root.Right.Right.Val = %d, want 7", result.Right.Right.Val)
	}
}

func TestRateLimiterNilSubtrees(t *testing.T) {
	serialize, deserialize := rate_limiter()

	root := &TreeNode{
		Val:  1,
		Left: &TreeNode{Val: 2},
	}

	data := serialize(root)
	result := deserialize(data)

	if result.Left == nil {
		t.Error("expected left child to exist")
	}
	if result.Right != nil {
		t.Error("expected right child to be nil")
	}
	if result.Left.Left != nil {
		t.Error("expected left-left grandchild to be nil")
	}
	if result.Left.Right != nil {
		t.Error("expected left-right grandchild to be nil")
	}
}
